function premiumHero(){return `<section class="hero premium-hero"><div class="hero-aurora" aria-hidden="true"><i></i><i></i><i></i></div><div class="hero-grid-lines" aria-hidden="true"></div><div class="container"><div class="hero-grid"><div class="hero-copy"><div class="hero-kicker">${icon('spark')}${t('Your next chapter of growth','الفصل الجاي من نمو أعمالك')}</div><h1>${t('Your business<br>in one <em class="gradient-text">powerful loop</em>','كل أعمالك<br>في <em class="gradient-text">دائرة واحدة</em>')}</h1><p class="hero-description">${t('Connect your customers, conversations and marketing in one workspace built around the way you grow','اربط عملاءك ومحادثاتك وتسويقك في مساحة واحدة مصممة حول طريقة نمو نشاطك')}</p><div class="hero-cta"><button class="btn btn-coral" data-action="plan">${t('Build your loop','ابنِ دائرتك')}${icon('arrow')}</button><button class="btn btn-glass" data-action="tour">${icon('play')}${t('Explore the experience','اكتشف التجربة')}</button></div><div class="hero-proof"><span>${icon('globe')}${t('Arabic & English','عربي وإنجليزي')}</span><span>${icon('users')}${t('Built around your team','مصممة حول فريقك')}</span></div></div><div class="hero-stage premium-stage"><div class="stage-halo" aria-hidden="true"></div><svg class="connection-lines" viewBox="0 0 650 540" fill="none" aria-hidden="true"><path d="M60 100C250 40 400 20 570 120M55 440C240 510 430 485 585 390M45 170C110 300 560 270 620 360" stroke="currentColor"/><path class="energy-path" d="M60 100C250 40 400 20 570 120M55 440C240 510 430 485 585 390" stroke="#ff9875"/></svg><div class="orbit-chip chip-whatsapp">${brandIcon('whatsapp')}<span>WhatsApp</span></div><div class="orbit-chip chip-mail">${icon('mail')}<span>${t('Marketing','التسويق')}</span></div><div class="orbit-chip chip-ai">${icon('spark')}<span>${t('AI assisted','مساعدة ذكية')}</span></div><div class="hero-console" id="hero-console"><div class="console-toolbar">${logo(true)}<span class="demo-pill">${t('Interactive demo','عرض تفاعلي')}</span></div><div class="console-tabs" role="group" aria-label="${t('Explore the hero demo','اكتشف العرض التفاعلي')}">${[['crm','crm','CRM','العملاء'],['inbox','inbox','Inbox','الرسائل'],['automation','automation','Automation','الأتمتة']].map(([k,i,en,ar])=>`<button data-hero-mode="${k}" aria-pressed="${k===heroMode}" class="${k===heroMode?'active':''}">${icon(i)}${t(en,ar)}</button>`).join('')}</div><div class="console-screen" id="console-screen">${heroScreen()}</div><div class="console-bottom"><span>${icon('spark')}${t('See a sample journey unfold','شوف رحلة توضيحية تتحرك')}</span><button id="hero-run" data-action="run-demo" aria-controls="console-screen" aria-pressed="${heroPlaying}">${icon(heroPlaying?'pause':'play')}${heroPlaying?t('Pause demo','إيقاف العرض'):t('Run demo','تشغيل العرض')}</button></div></div><div class="hero-live-card" id="hero-live-card">${heroLiveCard()}</div></div></div><div class="hero-bottom">${[['crm',t('Know your customers','اعرف عملاءك'),t('Keep the whole picture together','اجمع الصورة كاملة')],['automation',t('Keep things moving','خلّي الرحلة مستمرة'),t('A clear next step for every lead','خطوة واضحة لكل عميل')],['chart',t('Grow with clarity','انمُ بوضوح'),t('From your first enquiry to your next chapter','من أول استفسار للفصل الجاي')]].map(([i,a,b])=>`<div class="hero-bottom-item"><span class="hero-value-icon">${icon(i)}</span><div><b>${a}</b><small>${b}</small></div></div>`).join('')}</div></div></section>`}
function heroScreen(){const stages=[t('New lead','عميل جديد'),t('Connected','تم التواصل'),t('Following up','قيد المتابعة'),t('Confirmed','تم التأكيد')];if(heroMode==='crm')return `<div class="console-heading"><div><span>${t('YOUR SALES JOURNEY','رحلة المبيعات')}</span><h3>${t('Every lead has a next step','كل عميل له خطوة جاية')}</h3></div>${icon('chart')}</div><div class="console-metrics"><div><span>${t('Sample enquiries','استفسارات توضيحية')}</span><strong>24</strong></div><div><span>${t('In progress','قيد المتابعة')}</span><strong>08</strong></div><div><span>${t('Confirmed','تم التأكيد')}</span><strong>06</strong></div></div><div class="console-journey">${stages.map((s,i)=>`<button data-hero-stage="${i}" class="${heroStage===i?'active':''}" aria-label="${s}" aria-pressed="${heroStage===i}"><span class="stage-block">${icon(['chat','inbox','automation','check'][i])}</span><span>${s}</span></button>`).join('')}</div><div class="console-lead"><span class="lead-avatar">${t('A','ع')}</span><div><strong>${t('A new customer','عميل جديد')}</strong><span>${t('A conversation becomes an opportunity','محادثة تتحول لفرصة')}</span></div><span class="lead-status">${stages[heroStage]}</span></div>`;
if(heroMode==='inbox')return `<div class="console-heading"><div><span>${t('ONE SHARED INBOX','صندوق رسائل واحد')}</span><h3>${t('A little more connected','تواصل أقرب وأسهل')}</h3></div>${icon('inbox')}</div><div class="console-message"><span>${brandIcon('whatsapp')}</span><p>${t('Hi, I’d like to know more about your services','مرحبًا، حاب أعرف أكثر عن خدماتكم')}</p></div><div class="console-message reply"><span>${icon('spark')}</span><p>${t('Happy to help — what are you looking for?','حياك الله، إيش الخدمة اللي مهتم فيها؟')}</p></div><div class="console-message"><span>${brandIcon('instagram')}</span><p>${t('Can we arrange a consultation?','ممكن نرتب موعد استشارة؟')}</p></div><div class="console-assignment">${icon('users')}${t('The right context for your whole team','كل التفاصيل متاحة لفريقك')}</div>`;
return `<div class="console-heading"><div><span>${t('A CONNECTED WORKFLOW','مسار عمل مترابط')}</span><h3>${t('Put the next step in motion','خلّي الخطوة الجاية تتحرك')}</h3></div>${icon('automation')}</div><div class="console-workflow">${[[0,'chat',t('New enquiry','استفسار جديد'),t('Trigger','البداية')],[1,'spark',t('Qualify & route','تأهيل وتحويل'),t('Review the context','مراجعة التفاصيل')],[2,'mail',t('Personal follow-up','متابعة شخصية'),t('Send the next message','إرسال الرسالة الجاية')],[3,'calendar',t('Confirm next step','تأكيد الخطوة الجاية'),t('Move the journey forward','استمرار الرحلة')]].map(([i,k,n,d])=>`<button data-hero-stage="${i}" aria-pressed="${heroStage===i}" class="${heroStage===i?'active':''}">${icon(k)}<div><strong>${n}</strong><span>${d}</span></div>${icon(heroStage>=i?'check':'chevron')}</button>`).join('')}</div>`}
function heroLiveCard(){return `<span class="live-icon">${icon(['chat','inbox','automation','calendar'][heroStage])}</span><div><strong>${[t('A new enquiry arrives','استفسار جديد وصل'),t('The conversation starts','المحادثة بدأت'),t('The follow-up stays personal','المتابعة مستمرة'),t('The next step is confirmed','الخطوة الجاية مؤكدة')][heroStage]}</strong><span>${t('Sample activity in your loop','نشاط توضيحي داخل دائرتك')}</span></div>`}
function updateHero(){const screen=document.getElementById('console-screen');if(!screen)return;screen.innerHTML=heroScreen();document.getElementById('hero-live-card').innerHTML=heroLiveCard();document.querySelectorAll('[data-hero-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.heroMode===heroMode);b.setAttribute('aria-pressed',b.dataset.heroMode===heroMode)});const run=document.getElementById('hero-run');run.setAttribute('aria-pressed',heroPlaying);run.innerHTML=icon(heroPlaying?'pause':'play')+(heroPlaying?t('Pause demo','إيقاف العرض'):t('Run demo','تشغيل العرض'));screen.classList.remove('screen-enter');void screen.offsetWidth;screen.classList.add('screen-enter')}
function stopHeroDemo(){heroPlaying=false;clearInterval(heroTimer);updateHero()}
function runHeroDemo(){heroPlaying=!heroPlaying;clearInterval(heroTimer);if(heroPlaying){heroStage=(heroStage+1)%4;heroTimer=setInterval(()=>{if(document.hidden)return;heroStage=(heroStage+1)%4;updateHero()},2200)}updateHero()}
function sectorIllustration(index){const s=sectors[index];return `<div class="sector-illustration ${s.color}" aria-hidden="true"><div class="sector-graphic-grid"></div><div class="sector-orbit"></div><div class="sector-object">${icon(s.icon)}</div><span class="sector-mini mini1">${icon('chat')}</span><span class="sector-mini mini2">${icon('calendar')}</span><span class="sector-mini mini3">${icon('chart')}</span><div class="sector-graphic-label">${icon('check')} ${t('A connected customer journey','رحلة عميل مترابطة')}</div></div>`}
function sectorSection(){return `<section id="solutions" class="section sectors-section"><div class="container"><div class="section-head"><div><div class="eyebrow">${icon('building')}${t('MADE FOR YOUR WAY OF WORKING','مصممة لطريقة شغلك')}</div><h2 class="section-heading">${t('Different businesses<br><span class="gradient-ink">One connected way to grow</span>','أنشطة مختلفة<br><span class="gradient-ink">وطريق مترابط للنمو</span>')}</h2></div><p>${t('Your business has its own rhythm — choose a sector and see how the journey can fit around it','لكل نشاط طريقة شغل مختلفة — اختار قطاعك وشوف إزاي الرحلة تتصمم حوله')}</p></div><div class="sector-options" role="group" aria-label="${t('Business sectors','قطاعات الأعمال')}">${sectors.map((s,i)=>`<button data-business="${i}" class="sector-option ${i===currentBusiness?'active':''}" aria-pressed="${i===currentBusiness}"><span class="sector-option-icon ${s.color}">${icon(s.icon)}</span><span>${t(...s.name)}</span>${icon('arrow')}</button>`).join('')}</div><div class="sector-detail" id="business-panel">${businessPanel()}</div></div></section>`}
function featureCatalogueSection(){return `<section id="features" class="section feature-section"><div class="container"><div class="section-head"><div><div class="eyebrow">${icon('layers')}${t('EXPLORE THE FULL WORKSPACE','اكتشف مساحة العمل كاملة')}</div><h2 class="section-heading">${t('The tools behind<br>your next chapter','أدوات تساعدك<br>في الفصل الجاي')}</h2></div><p>${t('Explore the features to consider for your setup — each scope is reviewed around your business and chosen plan','اكتشف المزايا اللي نقدر ندرسها لنظامك — كل نطاق يتراجع حسب نشاطك والباقه المختارة')}</p></div><div class="feature-filters" role="group" aria-label="${t('Feature categories','تصنيفات المزايا')}">${featureGroups.map(([k,en,ar])=>`<button data-feature-filter="${k}" class="${featureFilter===k?'active':''}" aria-pressed="${featureFilter===k}">${t(en,ar)}</button>`).join('')}</div><div class="feature-grid" id="feature-grid">${featureGrid()}</div></div></section>`}
function featureGrid(){return allFeatures.filter(f=>featureFilter==='all'||f[3]===featureFilter).map((f)=>`<button class="feature-card" data-feature="${allFeatures.indexOf(f)}"><span class="feature-icon ${f[3]}">${icon(f[0])}</span><h3>${t(f[1],f[2])}</h3><p>${t(f[4],f[5])}</p><span class="feature-more">${t('Explore feature','اكتشف الميزة')}${icon('arrow')}</span></button>`).join('')}
function showFeature(i){const f=allFeatures[i];openDialog(`<div class="feature-icon ${f[3]}">${icon(f[0])}</div><div class="dialog-eyebrow">${t('YOUR CONNECTED WORKSPACE','مساحة عملك المترابطة')}</div><h2 id="dialog-title">${t(f[1],f[2])}</h2><p>${t(f[4],f[5])}</p><div class="dialog-callout"><strong>${t('A scope to shape around you','نطاق نصمّمه حول احتياجاتك')}</strong>${t('Availability, channel permissions, account requirements and usage costs are reviewed as part of your final setup','الإتاحة وصلاحيات القنوات ومتطلبات الحساب ورسوم الاستخدام تتراجع ضمن تجهيز نظامك النهائي')}</div><button class="btn btn-dark" id="feature-plan">${t('Include in my setup','أضفها لخطتي')}${icon('arrow')}</button>`);document.getElementById('feature-plan').onclick=()=>{requestedFeatureIndex=i;showPlan(f[3]==='operations'?2:1)}}
function pricingSection(){return `<section id="pricing" class="section pricing-section"><div class="container"><div class="pricing-header"><div class="eyebrow">${icon('wallet')}${t('A PLAN FOR YOUR NEXT CHAPTER','خطة للفصل الجاي')}</div><h2 class="section-heading">${t('Start where you are<br><span class="gradient-ink">Grow from there</span>','ابدأ من مكانك<br><span class="gradient-ink">وانمُ خطوة بخطوة</span>')}</h2><p>${t('Choose the scope that fits your team — explore every feature and shape your setup before taking the next step','اختار النطاق اللي يناسب فريقك — اكتشف المزايا وجهّز نظامك قبل الخطوة الجاية')}</p><div class="billing-switch" role="group" aria-label="${t('Billing period','فترة الدفع')}"><button data-billing="monthly" aria-pressed="${billingPeriod==='monthly'}" class="${billingPeriod==='monthly'?'active':''}">${t('Monthly','شهري')}</button><button data-billing="annual" aria-pressed="${billingPeriod==='annual'}" class="${billingPeriod==='annual'?'active':''}">${t('Annually','سنوي')}</button></div><p class="price-status" id="price-status">${pricingStatus()}</p></div><div class="pricing-grid" id="pricing-grid">${pricingCards()}</div><div class="pricing-notes"><p>${t('Scope, usage limits, onboarding, support and third-party channel fees are confirmed before purchase','النطاق وحدود الاستخدام والتهيئة والدعم ورسوم القنوات الخارجية تتأكد قبل الشراء')}</p><button class="text-link" data-action="comparison">${t('Compare all features','قارن كل المزايا')}${icon('arrow')}</button></div></div></section>`}
function pricingStatus(){return pricingConfig.mode==='indicative'?t('Suggested pricing for review — final prices and taxes are not yet confirmed','أسعار مقترحة للمراجعة — الأسعار النهائية والضرائب لم تتأكد بعد'):t('Pricing is tailored to your scope — monthly and annual options can be reviewed','التسعير حسب نطاق نظامك — نقدر نراجع خيارات الدفع الشهري والسنوي')}
function premiumFooter(){return `<footer class="footer premium-footer"><div class="footer-light" aria-hidden="true"></div><div class="container"><div class="footer-banner"><div><div class="eyebrow">${icon('spark')}${t('PUT YOUR NEXT CHAPTER IN MOTION','خلّي الفصل الجاي يبدأ')}</div><h2>${t('Let’s close the loop','نكمّل الدائرة سوا')}</h2><p>${t('A clearer journey for your customers and a more connected day for your team','رحلة أوضح لعملاءك ويوم أكثر ترابطًا لفريقك')}</p></div><button class="btn btn-coral" data-action="plan">${t('Build your loop','ابنِ دائرتك')}${icon('arrow')}</button></div><div class="footer-main"><div class="footer-brand">${logo(true)}<p>${t('Customers, conversations and growth<br>In one connected workspace','عملاء ومحادثات ونمو<br>في مساحة عمل مترابطة')}</p><div class="footer-tool-icons">${['whatsapp','instagram','gmail','zapier'].map(s=>`<button data-brand="${s}" aria-label="${t('Explore ','اكتشف ')+brands.find(b=>b[1]===s)[0]}">${brandIcon(s)}</button>`).join('')}</div></div><div class="footer-column"><h3>${t('Platform','المنصة')}</h3><a href="#features">${t('All features','كل المزايا')}</a>${products.map((p,i)=>`<a href="#features" data-footer-feature="${[0,5,10,9,15][i]}">${t(...p.name)}</a>`).join('')}</div><div class="footer-column"><h3>${t('Explore','اكتشف')}</h3><a href="#journey">${t('Customer journey','رحلة العميل')}</a><a href="#solutions">${t('Business sectors','قطاعات الأعمال')}</a><a href="#capabilities">${t('Tool capabilities','وظائف الأدوات')}</a><a href="#integrations">${t('Integrations','التكاملات')}</a><a href="#pricing">${t('Plans & pricing','الباقات والتسعير')}</a><a href="#faq">${t('Questions & answers','الأسئلة والإجابات')}</a></div><div class="footer-column"><h3>${t('Get started','ابدأ')}</h3><button data-action="tour">${t('Interactive tour','جولة تفاعلية')}</button><button data-action="plan">${t('Build your setup','جهّز نظامك')}</button><button data-action="comparison">${t('Compare features','قارن المزايا')}</button><button data-action="about">${t('About Foloop','عن فولوب')}</button><button data-action="privacy">${t('Privacy in this preview','الخصوصية في النسخة دي')}</button></div></div><div class="footer-wordmark" aria-hidden="true">foloop</div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Foloop</span><span>${icon('globe')}${t('Arabic & English','عربي وإنجليزي')}</span><span>${t('Product visuals use illustrative data','واجهات المنتج ببيانات توضيحية')}</span><a href="#main" aria-label="${t('Back to top','العودة للأعلى')}">${t('Back to top','العودة للأعلى')}${icon('arrow')}</a></div></div></footer>`}
function initializeExperience(){
 clearInterval(heroTimer);heroPlaying=false;clearInterval(journeyTimer);journeyIsPlaying=false;const hero=document.querySelector('.premium-hero');if(hero){hero.onpointermove=e=>{const r=hero.getBoundingClientRect();hero.style.setProperty('--pointer-x',`${e.clientX-r.left}px`);hero.style.setProperty('--pointer-y',`${e.clientY-r.top}px`)}}
 if(experienceObserver)experienceObserver.disconnect();const elements=document.querySelectorAll('.section-head,.section-heading,.showroom,.sector-detail,.feature-card,.price-card,.integration-card,.setup-step,.faq-layout,.footer-banner');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduced&&'IntersectionObserver' in window){experienceObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');experienceObserver.unobserve(entry.target)}}),{threshold:.08});elements.forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',`${Math.min(i%4,3)*65}ms`);experienceObserver.observe(el)})}
 document.querySelectorAll('.feature-card,.sector-option,.price-card,.integration-card').forEach(el=>{el.onpointermove=e=>{const r=el.getBoundingClientRect();el.style.setProperty('--card-x',`${e.clientX-r.left}px`);el.style.setProperty('--card-y',`${e.clientY-r.top}px`)}});
}
