let selectedStack=new Set(['crm','mail','chat','calendar','automation']);
function valueSection(){return `<section id="why-foloop" class="section value-section"><div class="container"><div class="section-head"><div><div class="eyebrow">${icon('layers')}${t('WHY FOLOOP','ليه فولوب')}</div><h2 class="section-heading">${t('Less tool-hopping<br><span class="gradient-ink">More of the whole picture</span>','تنقّل أقل بين الأدوات<br><span class="gradient-ink">وصورة أوضح لشغلك</span>')}</h2></div><p>${t('Bring the workflows you rely on into one customer journey — choose the parts of your stack you want to connect','إدارة العملاء والبريد والحجوزات والأتمتة — وظائف بتستخدم لها أدوات مختلفة، مجتمعة في فولوب')}</p></div><div class="consolidation"><div class="scattered-tools"><div class="stack-label">${t('A scattered day','يوم بين أدوات كتير')}</div><div class="stack-options">${stackCategories.map(([k,en,ar])=>`<button data-stack="${k}" aria-pressed="${selectedStack.has(k)}" class="${selectedStack.has(k)?'active':''}">${icon(k)}<span>${t(en,ar)}</span><span class="stack-check">${icon('check')}</span></button>`).join('')}</div><p>${t('Different tabs, separate context and repeated handoffs','تبويبات مختلفة وتفاصيل متفرقة وتحويلات متكررة')}</p></div><div class="stack-equals" aria-hidden="true"><span>→</span></div><div class="connected-tools"><div class="stack-label">${t('A connected way to work','وظائف متعددة، منصة واحدة')}</div><div class="connected-logo">${logo(true)}</div><div class="connected-count" id="connected-count">${stackCount()}</div><div class="connected-mini">${icon('inbox')}${t('One customer view','صورة واحدة للعميل')}</div><div class="connected-mini">${icon('automation')}${t('A clear next step','خطوة جاية واضحة')}</div><div class="connected-mini">${icon('users')}${t('A team in the loop','فريق عارف كل التفاصيل')}</div></div></div><div class="value-benefits">${[['users',t('Fewer handoffs','تحويلات أقل'),t('Give your team the context to keep moving','كل التفاصيل اللي فريقك محتاجها في مكان واحد')],['chat',t('A more personal experience','تجربة أقرب للعميل'),t('Follow up with the whole conversation in view','تابع وأنت شايف المحادثة كاملة')],['chart',t('More clarity as you grow','وضوح أكتر مع النمو'),t('Understand the journey and improve the next step','افهم الرحلة وحسّن الخطوة الجاية')]].map(([i,n,d])=>`<div>${icon(i)}<h3>${n}</h3><p>${d}</p></div>`).join('')}</div><p class="scope-note">${t('Foloop can consolidate selected workflows — external accounts, API access, AI usage or channel fees may still be needed depending on your setup','فولوب تجمع الوظائف الأساسية المشابهة — التطبيقات المعروضة ليست داخل المنصة، وربط قنوات مثل واتساب قد يتطلب حسابًا ورسوم استخدام')}</p></div></section>`}
function stackCount(){return `<strong>${selectedStack.size}</strong><span>${t('core capabilities in one platform','وظائف أساسية في منصة واحدة')}</span>`}
function addonsSection(){return `<section id="addons" class="section addons-section"><div class="container"><div class="section-head"><div><div class="eyebrow">${icon('plus')}${t('ADD WHAT YOUR BUSINESS NEEDS','أضف اللي نشاطك محتاجه')}</div><h2 class="section-heading">${t('Your plan is the start<br>Make it your own','الباقة هي البداية<br>كمّلها حسب احتياجك')}</h2></div><p>${t('Explore optional services and usage-based scopes around your core plan','اكتشف الخدمات الاختيارية والنطاقات حسب الاستخدام فوق باقتك الأساسية')}</p></div><div class="addon-grid">${addonCatalogue.map(([i,en,ar,d,da,n,na],j)=>`<details class="addon-card"><summary><span class="addon-icon">${icon(i)}</span><span><strong>${t(en,ar)}</strong><small>${t('Quoted to scope','حسب نطاق الإضافة')}</small></span>${icon('plus')}</summary><div class="addon-content"><p>${t(d,da)}</p><div>${icon('info')}${t(n,na)}</div><button class="text-link" data-addon="${j}">${t('Add to my setup brief','أضفها لملخص خطتي')}${icon('arrow')}</button></div></details>`).join('')}</div></div></section>`}
function startSection(){return `<section id="get-started" class="section start-section"><div class="container"><div class="section-head"><div><div class="eyebrow">${icon('compass')}${t('HOW WE GET STARTED','إزاي نبدأ سوا')}</div><h2 class="section-heading">${t('A clear process<br>From your first conversation','خطوات واضحة<br>من أول محادثة')}</h2></div><p>${t('We start with your business, then shape the tools around it — explore what happens at each step','نبدأ بفهم نشاطك، ونصمّم الأدوات حوله — اكتشف إيه اللي بيحصل في كل خطوة')}</p></div><div class="start-grid">${[[t('Understand your business','نفهم نشاطك'),t('Map your channels, lead flow and the places customers get stuck','نرسم القنوات ورحلة العملاء وأماكن التعطّل'),t('You bring','إنت تجهّز'),t('Your goals, current tools and customer journey','أهدافك وأدواتك الحالية ورحلة عميلك')],[t('Agree the scope','نتفق على النطاق'),t('Choose your plan, optional add-ons and the outcomes to track','نختار الباقة والإضافات والنتائج اللي هنتابعها'),t('You receive','إنت تستلم'),t('A clear feature scope, quote and setup plan','نطاق مزايا واضح وسعر وخطة تجهيز')],[t('Connect & test','نربط ونختبر'),t('Configure the agreed channels and test the journey with your team','نجهّز القنوات المتفق عليها ونختبر الرحلة مع فريقك'),t('We check together','نراجع سوا'),t('Permissions, messages, routing and the next action','الصلاحيات والرسائل والتحويل والخطوة الجاية')],[t('Launch & improve','نبدأ ونحسّن'),t('Review the agreed metrics and refine your day-to-day workflows','نراجع المؤشرات المتفق عليها ونطوّر مسارات العمل'),t('We keep visible','نخلي واضح'),t('What is working and what needs attention','إيه اللي شغال وإيه اللي محتاج متابعة')]].map(([n,d,l,v],i)=>`<article class="start-card"><span class="start-number">0${i+1}</span><h3>${n}</h3><p>${d}</p><div class="start-deliverable"><strong>${l}</strong><span>${v}</span></div></article>`).join('')}</div><div class="start-cta"><p>${t('Not sure where to start? Get a free growth check first','مش عارف تبدأ منين؟ جرّب فحص النمو المجاني الأول')}</p><a class="btn btn-dark" href="#growth-check">${t('Check my business','افحص نشاطي')}${icon('arrow')}</a></div></div></section>`}
function growthCheckSection(){return `<section id="growth-check" class="section growth-section"><div class="container growth-layout"><div class="growth-copy"><div class="eyebrow">${icon('chart')}${t('YOUR FREE GROWTH CHECK','فحص نمو مجاني لنشاطك')}</div><h2 class="section-heading">${t('See where the next<br><span class="gradient-text">opportunity is hiding</span>','اكتشف الفرصة الجاية<br><span class="gradient-text">في رحلة عميلك</span>')}</h2><p class="section-intro">${t('Enter a few numbers from your business and get a free report with conversion insights, follow-up gaps and practical next steps','دخل شوية أرقام من نشاطك، وخد تقرير مجاني يوضح التحويل وفجوات المتابعة وخطوات عملية للتحسين')}</p><div class="growth-highlights"><span>${icon('check')}${t('Your numbers, clear insights','أرقامك، وتحليل واضح')}</span><span>${icon('download')}${t('A report you can keep','تقرير تقدر تحتفظ بيه')}</span><span>${icon('shield')}${t('No email capture or app connection','من غير طلب بريد أو ربط حسابات')}</span></div><div class="growth-illustration" aria-hidden="true"><div class="growth-mini-chart"><i></i><i></i><i></i><i></i><i></i></div><span>${icon('chart')}${t('Turn your numbers into a next step','حوّل أرقامك لخطوة جاية')}</span></div></div><div class="growth-form-card"><form id="growth-form"><h3>${t('Your business at a glance','نشاطك في أرقام')}</h3><p>${t('Use the same reporting period and count unconverted enquiries without follow-up','استخدم نفس فترة التقرير، واحسب الاستفسارات المفتوحة اللي لم تتحوّل بعد')}</p><label class="form-field">${t('Business name (optional)','اسم النشاط (اختياري)')}<input name="businessName" value="${growthReport?escapeHTML(growthReport.name):''}" maxlength="80" placeholder="${t('Your business','اسم نشاطك')}"></label><div class="growth-fields"><label class="form-field">${t('Enquiries received','الاستفسارات الواردة')}<input type="number" min="1" max="1000000" name="leads" value="${growthReport?growthReport.leads:''}" required placeholder="100" inputmode="numeric"></label><label class="form-field">${t('Sales or bookings','المبيعات أو الحجوزات')}<input type="number" min="0" max="1000000" name="conversions" value="${growthReport?growthReport.conversions:''}" required placeholder="20" inputmode="numeric"></label><label class="form-field">${t('Open enquiries without follow-up','استفسارات مفتوحة بدون متابعة')}<input type="number" min="0" max="1000000" name="missed" value="${growthReport?growthReport.missed:''}" required placeholder="25" inputmode="numeric"></label><label class="form-field">${t('Typical first reply','وقت أول رد غالبًا')}<select name="response"><option value="fast" ${growthReport?.response==='fast'?'selected':''}>${t('Under 15 minutes','أقل من 15 دقيقة')}</option><option value="hour" ${growthReport?.response==='hour'?'selected':''}>${t('15–60 minutes','من 15 لـ60 دقيقة')}</option><option value="day" ${growthReport?.response==='day'?'selected':''}>${t('1–24 hours','من ساعة لـ24 ساعة')}</option><option value="slow" ${growthReport?.response==='slow'?'selected':''}>${t('More than a day','أكثر من يوم')}</option></select></label></div><p class="audit-validation" id="audit-validation" role="alert"></p><button class="btn btn-coral" type="submit">${t('Get my free report','احصل على تقريري المجاني')}${icon('arrow')}</button><p class="audit-note">${t('A self-assessment from the figures you provide — it does not access your website or connected accounts','تقييم ذاتي من الأرقام اللي تدخلها — ما بيوصلش لموقعك أو حساباتك المرتبطة')}</p></form><div id="growth-result" aria-live="polite">${growthReport?renderGrowthResult():''}</div></div></div></section>`}
let growthReport=null;
function calculateGrowthReport(fd){const leads=Number(fd.get('leads')),conversions=Number(fd.get('conversions')),missed=Number(fd.get('missed')),response=fd.get('response');if(!Number.isInteger(leads)||!Number.isInteger(conversions)||!Number.isInteger(missed)||leads>1000000||conversions>1000000||missed>1000000||leads<1||conversions<0||missed<0||conversions>leads||missed>leads-conversions)return {error:t('Sales and unattended enquiries must fit within the total enquiries you received','المبيعات والاستفسارات مفتوحة بدون متابعة لازم يكون مجموعهم ضمن إجمالي الاستفسارات الواردة')};const conversion=Math.round(conversions/leads*1000)/10;const coverage=Math.round((leads-missed)/leads*1000)/10;const actions=[];if(missed>0)actions.push(t(`Start with the ${missed} enquiries without follow-up — give each an owner and a next action`,`ابدأ بالـ${missed} استفسار بدون متابعة — حدّد مسؤول وخطوة جاية لكل واحد`));if(response==='day'||response==='slow')actions.push(t('Review first-response ownership and opening-hour coverage to reduce the wait','راجع مسؤولية أول رد وتغطية ساعات العمل لتقليل وقت الانتظار'));else actions.push(t('Keep response ownership clear and review unanswered conversations daily','حافظ على وضوح مسؤولية الرد وراجع المحادثات بدون رد يوميًا'));actions.push(t('Track enquiry source, next action and outcome in one pipeline','تتبّع مصدر الاستفسار والخطوة الجاية والنتيجة في مراحل بيع واحدة'));actions.push(t('Compare the same figures next month to measure progress against your own baseline','قارن نفس الأرقام الشهر الجاي لقياس التحسّن مقابل نقطة بدايتك'));return {name:String(fd.get('businessName')||t('Your business','نشاطك')).trim(),leads,conversions,missed,response,conversion,coverage,actions}}
function renderGrowthResult(){const r=growthReport;return `<div class="audit-report"><div class="report-heading">${icon('chart')}<div><span>${t('YOUR FREE REPORT','تقريرك المجاني')}</span><h3>${escapeHTML(r.name)}</h3></div></div><div class="report-metrics"><div><strong>${r.conversion}%</strong><span>${t('Conversion rate','معدل التحويل')}</span></div><div><strong>${r.coverage}%</strong><span>${t('Follow-up coverage','تغطية المتابعة')}</span></div><div><strong>${r.missed}</strong><span>${t('Enquiries to revisit','استفسارات للمتابعة')}</span></div></div><div class="report-bars">${[[r.leads,t('Received','وارد'),100],[r.conversions,t('Converted','تحوّل'),r.conversion],[r.missed,t('No follow-up','بدون متابعة'),r.missed/r.leads*100]].map(([v,n,p],i)=>`<div><span>${n}<b>${v}</b></span><div class="report-bar"><i class="bar-${i}" style="width:${p}%"></i></div></div>`).join('')}</div><h4>${t('Your next steps','خطواتك الجاية')}</h4><ol>${r.actions.map(a=>`<li>${a}</li>`).join('')}</ol><div class="report-definition">${t('Conversion = sales or bookings ÷ enquiries<br>Coverage = enquiries with follow-up ÷ all enquiries<br>Process suggestions are not revenue forecasts or industry benchmarks','التحويل = المبيعات أو الحجوزات ÷ الاستفسارات<br>التغطية = الاستفسارات المتابَعة ÷ كل الاستفسارات<br>المقترحات تخص طريقة العمل وليست توقعات إيراد أو معايير قطاعية')}</div><div class="dialog-actions"><button class="btn btn-dark" data-action="download-report">${icon('download')}${t('Download report','تنزيل التقرير')}</button><button class="btn btn-outline" data-action="plan">${t('Build my next step','جهّز خطوتي الجاية')}${icon('arrow')}</button></div></div>`}
function downloadGrowthReport(){if(!growthReport)return;const r=growthReport;const title=t('Foloop — Your free growth check','فولوب — تقرير فحص النمو المجاني');const report=`<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>body{font-family:Arial,sans-serif;max-width:850px;margin:40px auto;padding:30px;line-height:1.9;color:#172134}h1{font-size:30px}h2{font-size:24px}table{border-collapse:collapse;width:100%;margin:30px 0}td{padding:14px;border:1px solid #e3e8ef}p{color:#5a6577}.note{padding:20px;background:#f5f7fa;border-radius:12px}@media print{body{margin:0}}</style><h1>${title}</h1><h2>${escapeHTML(r.name)}</h2><p dir="ltr">${escapeHTML(r.website)}</p><p>${t('Based only on the figures you provided for one reporting period','مبني فقط على الأرقام اللي أدخلتها لفترة تقرير واحدة')}</p><table>${[[t('Enquiries received','الاستفسارات الواردة'),r.leads],[t('Sales or bookings','المبيعات أو الحجوزات'),r.conversions],[t('Enquiries without follow-up','استفسارات مفتوحة بدون متابعة'),r.missed],[t('Conversion rate','معدل التحويل'),r.conversion+'%'],[t('Follow-up coverage','تغطية المتابعة'),r.coverage+'%']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')}</table><h2>${t('Practical next steps','خطوات عملية')}</h2><ol>${r.actions.map(a=>`<li>${escapeHTML(a)}</li>`).join('')}</ol><p class="note">${t('Conversion = sales or bookings divided by enquiries<br>Follow-up coverage = (all enquiries − enquiries without follow-up) divided by all enquiries<br>This is a self-assessment, not an external analytics audit, revenue forecast or industry benchmark<br>No account data was accessed or submitted','التحويل = المبيعات أو الحجوزات مقسومة على الاستفسارات<br>تغطية المتابعة = (كل الاستفسارات − الاستفسارات مفتوحة بدون متابعة) مقسومة على كل الاستفسارات<br>ده تقييم ذاتي وليس تحليلًا خارجيًا أو توقع إيرادات أو معيارًا قطاعيًا<br>لم يتم الوصول لبيانات حسابات أو إرسالها')}</p><p>Foloop · ${new Date().toLocaleDateString(lang==='ar'?'ar-SA':'en-GB')}</p></html>`;const u=URL.createObjectURL(new Blob([report],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=`foloop-growth-report-${lang}.html`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),10000);notify(t('Your report is ready to save','تقريرك جاهز للحفظ'))}
function bindGrowthCheck(){const f=document.getElementById('growth-form');if(!f)return;f.onsubmit=e=>{e.preventDefault();const result=calculateGrowthReport(new FormData(f));const error=document.getElementById('audit-validation');error.textContent=result.error||'';if(result.error)return;growthReport=result;document.getElementById('growth-result').innerHTML=renderGrowthResult();document.getElementById('growth-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})}}
let narrative='service', journeyIsPlaying=false, journeyTimer=null, journeyPointerFrame=null;
const conversations={
 service:[[['Hi, I’d like to learn about your services','مرحبًا، حاب أعرف أكثر عن خدماتكم'],['Happy to help — which service are you interested in?','حياك الله، إيش الخدمة اللي مهتم فيها؟']],[['I’m interested in a consultation','مهتم باستشارة'],['Great — shall we find a time that works for you?','ممتاز، نرتب لك وقت مناسب؟']],[['Let me check my schedule first','خليني أراجع وقتي الأول'],['Just checking in — would Thursday at 4 work for you?','حبيت أتابع معك، يناسبك الخميس الساعة 4؟']],[['That works, please confirm it','مناسب، أكدوا لي الموعد'],['Your next appointment is confirmed — we’ll send you the details','تم تأكيد موعدك، بنرسل لك التفاصيل']]],
 store:[[['Hi, I have a question about a product','مرحبًا، عندي سؤال عن منتج'],['Of course — which product are you looking at?','أكيد، إيش المنتج اللي مهتم فيه؟']],[['I’d like to understand the available options','حاب أعرف الخيارات المتاحة'],['Here are the options — what matters most to you?','هذي الخيارات، إيش الأكثر أهمية لك؟']],[['I’ll take a look and get back to you','بشوف الخيارات وأرجع لكم'],['Happy to help if you have questions — shall we walk through the options?','يسعدنا نساعدك لو عندك أسئلة، نراجع الخيارات سوا؟']],[['I’m ready for the next step','جاهز للخطوة الجاية'],['Great — here are the details for your chosen option','ممتاز، هذي تفاصيل الخيار المناسب لك']]],
 agency:[[['I’m looking for help with my marketing','أحتاج مساعدة في التسويق'],['Tell us a little about your business and goals','احك لنا شوية عن نشاطك وأهدافك']],[['We want a clearer lead follow-up process','نحتاج متابعة أوضح للعملاء'],['Let’s map the journey and scope the right approach','نرسم الرحلة ونحدّد الطريقة المناسبة']],[['We’re reviewing the scope with the team','نراجع النطاق مع الفريق'],['Would a short call help answer your team’s questions?','تحب نرتب مكالمة قصيرة نجاوب فيها على أسئلة الفريق؟']],[['Yes, let’s arrange the call','تمام، نرتب المكالمة'],['Your discovery call is confirmed — we’ll review your goals together','تم تأكيد مكالمة البداية، بنراجع أهدافكم سوا']]]
};
function journeySection(){return `<section id="journey" class="section journey-section interactive-journey"><div class="journey-ambient" aria-hidden="true"></div><div class="container"><div class="section-head"><div><div class="eyebrow">${icon('chat')}${t('YOU CONTROL THE JOURNEY','إنت بتتحكم في الرحلة')}</div><h2 class="section-heading">${t('Good business starts<br><span class="gradient-text">with a conversation</span>','الشغل يبدأ<br><span class="gradient-text">بمحادثة</span>')}</h2></div><p>${t('Move your cursor across this section to guide the conversation — or use the steps and slider','حرّك الماوس داخل القسم عشان تتحكم في المحادثة — أو استخدم الخطوات وشريط التحكم')}</p></div><div class="journey-settings"><div class="scenario-switch" role="group" aria-label="${t('Conversation example','مثال المحادثة')}">${[['service','Services','الخدمات'],['store','Retail','المتاجر'],['agency','Agencies','الوكالات']].map(([k,en,ar])=>`<button data-narrative="${k}" class="${narrative===k?'active':''}" aria-pressed="${narrative===k}">${t(en,ar)}</button>`).join('')}</div><button class="journey-play" data-action="play-journey" id="journey-play" aria-controls="journey-preview" aria-pressed="${journeyIsPlaying}">${icon(journeyIsPlaying?'pause':'play')}${t('Play journey','تشغيل الرحلة')}</button></div><div class="journey-layout"><div class="journey-steps">${journeySteps.map((s,i)=>`<button class="journey-step ${i===currentJourney?'active':''}" data-journey="${i}" aria-pressed="${i===currentJourney}"><span class="step-number">0${i+1}</span><div><h3>${t(...s.name)}</h3><p>${t(...s.description)}</p></div></button>`).join('')}</div><div class="journey-preview" id="journey-preview" aria-live="polite">${journeyPreview()}</div></div><div class="journey-scrubber"><label for="journey-range">${icon('compass')}${t('Your journey control','التحكم في الرحلة')}</label><input id="journey-range" aria-valuetext="${t(...journeySteps[currentJourney].name)}" type="range" min="0" max="3" step="1" value="${currentJourney}" aria-label="${t('Customer journey step','مرحلة رحلة العميل')}"><span id="journey-current">${t(...journeySteps[currentJourney].name)}</span></div><div class="journey-bottom"><p>${t('Illustrative conversations — one shared customer record keeps the context connected','محادثات توضيحية — ملف عميل واحد يحافظ على ترابط التفاصيل')}</p><button class="text-link" data-action="tour">${t('Take the guided tour','ابدأ الجولة التوضيحية')}${icon('arrow')}</button></div></div></section>`}
function updateJourney(i){currentJourney=i;document.querySelectorAll('[data-journey]').forEach((b,j)=>{b.classList.toggle('active',j===i);b.setAttribute('aria-pressed',j===i)});const p=document.getElementById('journey-preview');if(p){p.innerHTML=journeyPreview();p.classList.remove('conversation-enter');void p.offsetWidth;p.classList.add('conversation-enter')}const range=document.getElementById('journey-range');if(range){range.value=i;range.setAttribute('aria-valuetext',t(...journeySteps[i].name))}const label=document.getElementById('journey-current');if(label)label.textContent=t(...journeySteps[i].name)}
function stopJourney(){journeyIsPlaying=false;clearInterval(journeyTimer);const b=document.getElementById('journey-play');if(b){b.setAttribute('aria-pressed','false');b.innerHTML=icon('play')+t('Play journey','تشغيل الرحلة')}}
function playJourney(){journeyIsPlaying=!journeyIsPlaying;clearInterval(journeyTimer);if(journeyIsPlaying){updateJourney((currentJourney+1)%4);journeyTimer=setInterval(()=>{if(!document.hidden)updateJourney((currentJourney+1)%4)},2800)}document.getElementById('journey-play').setAttribute('aria-pressed',journeyIsPlaying);document.getElementById('journey-play').innerHTML=icon(journeyIsPlaying?'pause':'play')+(journeyIsPlaying?t('Pause journey','إيقاف الرحلة'):t('Play journey','تشغيل الرحلة'))}
function bindJourneyControl(){const section=document.querySelector('.interactive-journey');if(!section)return;section.onpointermove=e=>{const r=section.getBoundingClientRect();section.style.setProperty('--pointer-x',`${e.clientX-r.left}px`);section.style.setProperty('--pointer-y',`${e.clientY-r.top}px`);if(e.pointerType!=='mouse'||e.target.closest('button,input,a'))return;if(journeyIsPlaying)stopJourney();if(journeyPointerFrame)cancelAnimationFrame(journeyPointerFrame);const ratio=(e.clientX-r.left)/r.width;const step=Math.max(0,Math.min(3,Math.floor((lang==='ar'?1-ratio:ratio)*4)));journeyPointerFrame=requestAnimationFrame(()=>{if(step!==currentJourney)updateJourney(step)})};document.getElementById('journey-range').oninput=e=>{stopJourney();updateJourney(Number(e.target.value))};document.querySelectorAll('[data-journey]').forEach(b=>{b.onpointerenter=e=>{if(e.pointerType==='mouse'&&!journeyIsPlaying)updateJourney(Number(b.dataset.journey))}})}
function animatedChannelRail(){const items=[['whatsapp','WhatsApp'],['instagram','Instagram'],['facebook','Facebook'],['messenger','Messenger'],['tiktok','TikTok'],['youtube','YouTube'],['linkedin','LinkedIn'],['gmail','Gmail'],['snapchat','Snapchat'],['pinterest','Pinterest']];const copy=hidden=>`<div class="marquee-group" ${hidden?'aria-hidden="true"':''}>${items.map(([s,n])=>`<div class="rail-brand">${brandIcon(s)}<span>${n}</span></div>`).join('')}</div>`;return `<section class="channel-rail" aria-label="${t('Customer channels','قنوات العملاء')}"><div class="container rail-heading"><p>${t('Your customers are everywhere<br><strong>Bring the conversation together</strong>','عملاؤك موجودين في أماكن كتير<br><strong>اجمع المحادثة في مكان واحد</strong>')}</p><button class="rail-pause" data-action="pause-rail" aria-pressed="false" aria-label="${t('Pause moving logos','إيقاف حركة الشعارات')}">${icon('pause')}</button></div><div class="marquee">${copy(false)+copy(true)}</div></section>`}
